mapper.insert:
INSERT INTO member_coupons (coupon_id, member_id)
SELECT #{couponId}, #{memberId}
FROM coupons c
WHERE c.id = #{couponId}
  AND c.target_type = 'NEW_MEMBERS'
  AND c.status = 'ACTIVE'
  AND c.starts_at <= NOW(6)
  AND c.expires_at > NOW(6)
  AND NOT EXISTS (
      SELECT 1
      FROM member_coupons mc
      WHERE mc.coupon_id = #{couponId}
        AND mc.member_id = #{memberId}
  )
